(function () {
  window.addEventListener("load", () => {
    setTimeout(() => {
      window.scrollTo(0, 0);
    }, 50);
  });

  ("use strict");
  var BIRD_SRC =
    "data:image/png;base64,";
  document.querySelectorAll(".bird-asset").forEach(function (img) {
    img.src = BIRD_SRC;
  });
  var MAHMOUD_SRC =
    "data:image/png;base64,";
  var PROFILE_SRC = "assets/profile.png";
  document.querySelectorAll(".mahmoud-asset").forEach(function (img) {
    img.onerror = function () {
      img.onerror = null;
      img.src = MAHMOUD_SRC;
    };
    img.src = PROFILE_SRC;
  });
  var reduceMotion = window.matchMedia(
    "(prefers-reduced-motion: reduce)",
  ).matches;
  gsap.registerPlugin(ScrollTrigger);

  /* ---------- Custom cursor ---------- */
  var isTouch = window.matchMedia("(hover:none), (pointer:coarse)").matches;
  var dot = document.getElementById("cursor-dot");
  var label = document.getElementById("cursor-label");
  if (!isTouch) {
    window.addEventListener("mousemove", function (e) {
      dot.style.left = e.clientX + "px";
      dot.style.top = e.clientY + "px";
      label.style.left = e.clientX + 26 + "px";
      label.style.top = e.clientY + 4 + "px";
    });
    document.addEventListener("mouseover", function (e) {
      var el = e.target.closest("a,button");
      if (el) {
        dot.classList.add("hover");
        var txt = el.classList.contains("project-panel")
          ? "EXPLORE"
          : el.closest(".project-panel")
            ? "EXPLORE"
            : "OPEN";
        label.textContent = el.dataset.cursor || txt;
        label.classList.add("show");
      }
    });
    document.addEventListener("mouseout", function (e) {
      var el = e.target.closest("a,button");
      if (el) {
        dot.classList.remove("hover");
        label.classList.remove("show");
      }
    });
  }

  /* ---------- Scroll progress ---------- */
  var progressBar = document.getElementById("progress-bar");
  window.addEventListener("scroll", function () {
    var h = document.documentElement;
    var pct = (h.scrollTop / (h.scrollHeight - h.clientHeight)) * 100;
    progressBar.style.width = pct + "%";
  });

  /* ---------- Nav ---------- */
  var navbar = document.getElementById("navbar");
  var navToggle = document.getElementById("navToggle");
  var navLinks = document.getElementById("navLinks");
  navToggle.addEventListener("click", function () {
    var open = navLinks.classList.toggle("open");
    navToggle.setAttribute("aria-expanded", open);
  });
  document.querySelectorAll("[data-target]").forEach(function (btn) {
    btn.addEventListener("click", function () {
      var target = document.querySelector(btn.dataset.target);
      if (target) {
        target.scrollIntoView({
          behavior: reduceMotion ? "auto" : "smooth",
        });
      }
      navLinks.classList.remove("open");
      navToggle.setAttribute("aria-expanded", false);
    });
  });
  var sections = [
    "#solution-statement",
    "#about",
    "#education",
    "#skills",
    "#services",
    "#projects",
    "#contact",
  ].map(function (s) {
    return document.querySelector(s);
  });
  var navButtons = document.querySelectorAll(".nav-links button");
  function setActiveNav() {
    var pos = window.scrollY + window.innerHeight * 0.35;
    var activeIdx = 0;
    sections.forEach(function (sec, i) {
      if (sec && sec.offsetTop <= pos) {
        activeIdx = i;
      }
    });
    navButtons.forEach(function (b, i) {
      b.classList.toggle("active", i === activeIdx);
    });
    navbar.classList.toggle(
      "visible",
      window.scrollY > window.innerHeight * 0.6,
    );
  }
  window.addEventListener("scroll", setActiveNav);
  setActiveNav();

  /* ---------- Reveal on scroll ---------- */
  document.querySelectorAll(".reveal").forEach(function (el) {
    ScrollTrigger.create({
      trigger: el,
      start: "top 88%",
      onEnter: function () {
        el.classList.add("in");
      },
    });
  });

  /* ---------- Intro particles ---------- */
  var particleHost = document.getElementById("intro-particles");
  for (var i = 0; i < 26; i++) {
    var p = document.createElement("span");
    p.style.left = Math.random() * 100 + "%";
    p.style.top = Math.random() * 100 + "%";
    particleHost.appendChild(p);
  }
  gsap.to("#intro-particles span", {
    opacity: function () {
      return 0.15 + Math.random() * 0.35;
    },
    y: "-=40",
    duration: 3,
    stagger: { each: 0.08, from: "random", repeat: -1, yoyo: true },
  });

  /* ---------- Sequential intro story ---------- */
  var fightSection = document.getElementById("intro-fight");
  var solutionSection = document.getElementById("solution-statement");
  var aboutSection = document.getElementById("about");
  var skipBtn = document.getElementById("skip-intro");
  var solutionStarted = false;
  var aboutStarted = false;

  function smoothScrollToScene(target, callback) {
    var scene = document.querySelector(target);
    if (!scene) return;
    document.body.style.overflow = "";
    window.scrollTo({ top: scene.offsetTop, behavior: "smooth" });
    window.setTimeout(callback, 1300);
  }

  function revealSolution(instant) {
    if (solutionStarted) return;
    fightSection.style.display = "none";
    ScrollTrigger.refresh();
    document.body.style.overflow = "";
    solutionStarted = true;
    var play = function () {
      gsap
        .timeline({
          onComplete: function () {
            window.setTimeout(function () {
              if (aboutStarted || aboutSection.querySelector(".reveal.in"))
                return;
              aboutStarted = true;
              smoothScrollToScene("#about", function () {
                gsap.fromTo(
                  "#about .about-copy",
                  { opacity: 0.5, y: 24 },
                  { opacity: 1, y: 0, duration: 0.8, ease: "power2.out" },
                );
              });
            }, 900);
          },
        })
        .fromTo(
          "#solution-developer",
          { opacity: 0, y: 34, scale: 0.96 },
          {
            opacity: 1,
            y: 0,
            scale: 1,
            duration: 0.7,
            ease: "power3.out",
          },
        )
        .fromTo(
          "#solution-platforms",
          { opacity: 0, y: 34, scale: 0.96 },
          {
            opacity: 1,
            y: 0,
            scale: 1,
            duration: 0.7,
            ease: "power3.out",
          },
          "+=0.25",
        )
        .fromTo(
          "#solution-experience",
          { opacity: 0, y: 34, scale: 0.96 },
          {
            opacity: 1,
            y: 0,
            scale: 1,
            duration: 0.8,
            ease: "power3.out",
          },
          "+=0.25",
        )
        .fromTo(
          ".solution-support, .solution-actions",
          { opacity: 0, y: 18 },
          { opacity: 1, y: 0, duration: 0.6, ease: "power2.out" },
          "+=0.2",
        );
    };

    if (instant) {
      window.scrollTo(0, solutionSection.offsetTop);
      play();
    } else {
      smoothScrollToScene("#solution-statement", play);
    }
  }

  skipBtn.addEventListener("click", function () {
    if (typeof tl !== "undefined" && tl) tl.kill();
    ScrollTrigger.refresh();

    revealSolution(true);
  });

  gsap.set("#android-side", { xPercent: -160, yPercent: -50 });
  gsap.set("#ios-side", { xPercent: 160, yPercent: -50 });
  gsap.set("#bird-wrap", { xPercent: -50, yPercent: -220, scale: 0.6 });
  document.body.style.overflow = "hidden";

  if (reduceMotion) {
    revealSolution(true);
  } else {
    var tl = gsap.timeline({ delay: 0.3 });
    tl.to(
      "#android-side",
      { xPercent: 0, duration: 1, ease: "power3.out" },
      0.6,
    )
      .to("#ios-side", { xPercent: 0, duration: 1, ease: "power3.out" }, 0.6)
      .to("#android-speech", { opacity: 1, duration: 0.4 }, 1.7)
      .to("#ios-speech", { opacity: 1, duration: 0.4 }, 2.0)
      .to(
        "#android-side",
        {
          xPercent: 6,
          rotation: 2,
          scale: 1.03,
          duration: 0.15,
          repeat: 5,
          yoyo: true,
          ease: "power1.inOut",
        },
        2.4,
      )
      .to(
        "#ios-side",
        {
          xPercent: -6,
          rotation: -2,
          scale: 1.03,
          duration: 0.15,
          repeat: 5,
          yoyo: true,
          ease: "power1.inOut",
        },
        2.4,
      )
      .to("#android-speech, #ios-speech", { opacity: 0, duration: 0.3 }, 3.7)
      .to(
        "#android-side",
        { xPercent: -18, duration: 0.6, ease: "power2.out" },
        3.8,
      )
      .to("#ios-side", { xPercent: 18, duration: 0.6, ease: "power2.out" }, 3.8)
      .set("#bird-wrap", { opacity: 1 }, 4.0)
      .to(
        "#bird-wrap",
        { yPercent: -50, scale: 1, duration: 1.1, ease: "power3.out" },
        4.0,
      )
      .to("#line-enough", { opacity: 1, y: 0, duration: 0.5 }, 5.2)
      .to("#line-enough", { opacity: 0, y: -16, duration: 0.4 }, 6.0)
      .to("#line-solve", { opacity: 1, y: 0, duration: 0.6 }, 6.2)
      .to("#line-solve", { opacity: 0, y: -16, duration: 0.5 }, 7.2)
      .call(function () {
        revealSolution(false);
      });
  }

  gsap.to(".orbit-ring.r1", {
    rotate: 360,
    duration: 40,
    repeat: -1,
    ease: "none",
    transformOrigin: "50% 50%",
  });
  gsap.to(".orbit-ring.r2", {
    rotate: -360,
    duration: 60,
    repeat: -1,
    ease: "none",
    transformOrigin: "50% 50%",
  });

  /* ---------- Outro reveal ---------- */
  ScrollTrigger.create({
    trigger: "#outro",
    start: "top 70%",
    onEnter: function () {
      gsap
        .timeline()
        .to("#outro-bird", { opacity: 1, y: 0, duration: 0.8 })
        .to("#outro p.line1", { opacity: 1, duration: 0.6 }, "-=0.2")
        .to("#outro p.line2", { opacity: 1, duration: 0.6 }, "-=0.2")
        .to("#outro .final-name", { opacity: 1, duration: 0.6 }, "-=0.2");
    },
  });
})();
